-- rule retired_child_in_active_parent (row): parameterized; p1 boolean, p2 boolean
SELECT t."parent_id", t."child_id", count(*) AS "n" FROM "sxc_rules"."bom_line" t WHERE (EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."parent_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p1 AS boolean)))) AND (EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."child_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p2 AS boolean)))) GROUP BY t."parent_id", t."child_id";

-- rule retired_child_in_active_parent: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_retired_child_in_active_parent" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."child_id" COLLATE "C" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (SELECT t."parent_id", t."child_id", count(*) AS "n" FROM "sxc_rules"."bom_line" t WHERE (EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."parent_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(E'false' AS boolean)))) AND (EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."child_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(E'true' AS boolean)))) GROUP BY t."parent_id", t."child_id") r;

-- example retired_child_in_active_parent[0]: parameterized; 16 parameters
WITH "sxc_ex_bom_line"("parent_id", "child_id") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS text)), (CAST(:p3 AS text), CAST(:p4 AS text)), (CAST(:p5 AS text), CAST(:p6 AS text)), (CAST(:p7 AS text), CAST(:p8 AS text))), "sxc_ex_part"("part_id", "retired") AS (VALUES (CAST(:p9 AS text), CAST(:p10 AS boolean)), (CAST(:p11 AS text), CAST(:p12 AS boolean)), (CAST(:p13 AS text), CAST(:p14 AS boolean))) SELECT * FROM (SELECT t."parent_id", t."child_id", count(*) AS "n" FROM "sxc_ex_bom_line" t WHERE (EXISTS (SELECT 1 FROM "sxc_ex_part" n WHERE n."part_id" = t."parent_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p15 AS boolean)))) AND (EXISTS (SELECT 1 FROM "sxc_ex_part" n WHERE n."part_id" = t."child_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p16 AS boolean)))) GROUP BY t."parent_id", t."child_id") r;
